'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var Fcn = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Fcn, 'function', 'main export is a function' );
	t.end();
});

tape( 'a function instance has a `length` property', function test( t ) {
	var f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( hasProp( f, 'length' ), true, 'has property' );
	t.end();
});

tape( 'the property value equals the number of expected arguments', function test( t ) {
	var f;

	f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( f.length, 2, 'returns expected value' );
	t.end();
});

tape( 'the property value equals zero when the function has no parameters', function test( t ) {
	var f;

	f = new Fcn( 'return 42' );
	t.strictEqual( f.length, 0, 'returns expected value' );
	t.end();
});

tape( 'the property value equals one when the function has one parameter', function test( t ) {
	var f;

	f = new Fcn( 'x', 'return x * 2' );
	t.strictEqual( f.length, 1, 'returns expected value' );
	t.end();
});

tape( 'the property value equals three when the function has three parameters', function test( t ) {
	var f;

	f = new Fcn( 'x', 'y', 'z', 'return x + y + z' );
	t.strictEqual( f.length, 3, 'returns expected value' );
	t.end();
});
